//! Cross-implementation test vectors: the JavaScript reference implementation (@noble) and this core open each
//! other's output.
//!
//! - `tests/vectors/dev.json`  : generated by the JavaScript reference implementation, opened here
//! - `tests/vectors/rust.json` : generated by this file from a fixed seed, opened by the JavaScript reference implementation
//!
//! Both files have the same shape and are checked by the same `check`. rust.json is normally regenerated and only
//! compared with the file. To change it: `GORI_WRITE_VECTORS=1 cargo test --test vectors`.
//!
//! Since the post-quantum version, `keys.account`, `keys.enc` and `keys.guardians` are seeds; public keys are derived
//! from the seeds (src/pq.rs).
//! Envelopes are inner envelopes (104 B, `seal_inner`). Outer envelope, HEK and identity binding vectors live in
//! `tests/pq.rs` (`pq-rust.json`).

use std::path::PathBuf;

use gori_core::{shamir, Core, Error, Slot};
use rand_chacha::rand_core::{RngCore, SeedableRng};
use rand_chacha::ChaCha20Rng;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct Keys {
    account: String,
    device: String,
    enc: String,
    recovery: String,
    guardians: Vec<String>,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct Sig {
    slot: String,
    msg: String,
    sig: String,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct Pair {
    pt: String,
    ct: String,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
#[serde(rename_all = "camelCase")]
struct Recovery {
    threshold: usize,
    backup: String,
    server_share: String,
    guardian_shares: Vec<String>,
    resealed: Vec<String>,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct ShamirVector {
    secret: String,
    n: usize,
    k: usize,
    coefficients: String,
    shares: Vec<String>,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    generator: String,
    keys: Keys,
    pubs: Keys,
    signatures: Vec<Sig>,
    certificate: String,
    envelope: String,
    ciphertexts: Vec<Pair>,
    wrapped: String,
    wrapped_ciphertexts: Vec<Pair>,
    foreign_envelope: String,
    recovery: Recovery,
    shamir: Vec<ShamirVector>,
}

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap_or_else(|_| panic!("hex: {s}"))
}

fn x(b: &[u8]) -> String {
    hex::encode(b)
}

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

fn seeded(seed: u64) -> Core {
    Core::with_rng(Box::new(ChaCha20Rng::seed_from_u64(seed)))
}

fn slot_of(name: &str) -> Slot {
    match name {
        "account" => Slot::Account,
        "device" => Slot::Device,
        _ => panic!("slot {name}"),
    }
}

/// Inputs matching the vector shape: the same plaintexts as the JavaScript generator
fn plaintexts() -> Vec<Vec<u8>> {
    vec![
        vec![],
        b"a".to_vec(),
        // a multi-byte UTF-8 plaintext (2- and 3-byte sequences)
        "multi-byte: d\u{e9}j\u{e0} vu \u{2713}".as_bytes().to_vec(),
        (0..1000u32).map(|i| (i * 7 % 256) as u8).collect(),
    ]
}

fn messages() -> Vec<Vec<u8>> {
    vec![vec![], b"gori".to_vec(), (0..300u32).map(|i| i as u8).collect()]
}

/// Build the Rust vectors from a fixed seed
fn generate() -> Fixture {
    let mut rng = ChaCha20Rng::seed_from_u64(0x6f72_6921);
    let mut key = || {
        let mut k = [0u8; 32];
        rng.fill_bytes(&mut k);
        k
    };
    let (account, device, enc, recovery) = (key(), key(), key(), key());
    let guardians: Vec<[u8; 32]> = (0..3).map(|_| key()).collect();
    let foreign = key();
    let shamir_secret = key();
    let mut coeffs = vec![0u8; 32 * 2];
    rng.fill_bytes(&mut coeffs);

    let mut me = seeded(1);
    let pubs = Keys {
        account: x(&me.load(Slot::Account, &account).unwrap()),
        device: x(&me.load(Slot::Device, &device).unwrap()),
        enc: x(&me.load(Slot::Enc, &enc).unwrap()),
        recovery: x(&gori_core::crypto::x25519_public(&recovery)),
        // Guardian keys are encryption seeds too; the public key is the X25519 key derived from the seed (post-quantum version)
        guardians: guardians.iter().map(|g| x(&Slot::Enc.public_from(g))).collect(),
    };

    let mut signatures = Vec::new();
    for slot in ["account", "device"] {
        for m in messages() {
            signatures.push(Sig { slot: slot.into(), msg: x(&m), sig: x(&me.sign(slot_of(slot), &m).unwrap()) });
        }
    }
    let certificate = x(&me.certify_device(&h(&pubs.device)).unwrap());

    // The sender is a separate core; the envelope is sealed to my enc public key
    let mut sender = seeded(2);
    let k1 = sender.create_content_key();
    let k2 = sender.create_content_key();
    let envelope = x(&sender.seal_inner(&k1, &h(&pubs.enc)).unwrap());
    let ciphertexts = plaintexts()
        .into_iter()
        .map(|pt| Pair { ct: x(&sender.encrypt(&k1, &pt).unwrap()), pt: x(&pt) })
        .collect();
    let wrapped = x(&sender.wrap_key(&k1, &k2).unwrap());
    let wrapped_ciphertexts = plaintexts()
        .into_iter()
        .take(3)
        .map(|pt| Pair { ct: x(&sender.encrypt(&k2, &pt).unwrap()), pt: x(&pt) })
        .collect();
    let foreign_envelope =
        x(&sender.seal_inner(&k1, &gori_core::crypto::x25519_public(&foreign)).unwrap());

    let kit = me.prepare_recovery(&pubs.guardians.iter().map(|g| h(g)).collect::<Vec<_>>(), 2).unwrap();
    let resealed = guardians
        .iter()
        .zip(&kit.guardian_shares)
        .enumerate()
        .map(|(i, (g, share))| {
            let mut gc = seeded(100 + i as u64);
            gc.load(Slot::Enc, g).unwrap();
            x(&gc.reseal_share(share, &h(&pubs.recovery)).unwrap())
        })
        .collect();

    let shamir_vectors = vec![
        (shamir_secret.to_vec(), 3, 2, coeffs[..32].to_vec()),
        (shamir_secret.to_vec(), 5, 3, coeffs.clone()),
        (vec![0x42], 2, 2, vec![0x99]),
    ]
    .into_iter()
    .map(|(secret, n, k, c)| ShamirVector {
        shares: shamir::split(&secret, n, k, &c).unwrap().iter().map(|s| x(s)).collect(),
        secret: x(&secret),
        n,
        k,
        coefficients: x(&c),
    })
    .collect();

    Fixture {
        generator: "gori-core (Rust), seed 0x6f726921".into(),
        keys: Keys {
            account: x(&account),
            device: x(&device),
            enc: x(&enc),
            recovery: x(&recovery),
            guardians: guardians.iter().map(|g| x(g)).collect(),
        },
        pubs,
        signatures,
        certificate,
        envelope,
        ciphertexts,
        wrapped,
        wrapped_ciphertexts,
        foreign_envelope,
        recovery: Recovery {
            threshold: 2,
            backup: x(&kit.backup),
            server_share: x(&kit.server_share[..]),
            guardian_shares: kit.guardian_shares.iter().map(|s| x(s)).collect(),
            resealed,
        },
        shamir: shamir_vectors,
    }
}

/// Check one vector set fully against this core
fn check(f: &Fixture) {
    let who = &f.generator;
    let mut me = seeded(7);
    assert_eq!(x(&me.load(Slot::Account, &h(&f.keys.account)).unwrap()), f.pubs.account, "{who}: account pub");
    assert_eq!(x(&me.load(Slot::Device, &h(&f.keys.device)).unwrap()), f.pubs.device, "{who}: device pub");
    assert_eq!(x(&me.load(Slot::Enc, &h(&f.keys.enc)).unwrap()), f.pubs.enc, "{who}: enc pub");
    assert_eq!(
        x(&gori_core::crypto::x25519_public(&h(&f.keys.recovery).try_into().unwrap())),
        f.pubs.recovery,
        "{who}: recovery pub"
    );

    // Ed25519 is deterministic, so signatures must match byte for byte
    for s in &f.signatures {
        let msg = h(&s.msg);
        let slot = slot_of(&s.slot);
        let pubkey = if slot == Slot::Account { &f.pubs.account } else { &f.pubs.device };
        assert_eq!(x(&me.sign(slot, &msg).unwrap()), s.sig, "{who}: sig {} {}", s.slot, s.msg);
        assert!(Core::verify(&h(pubkey), &msg, &h(&s.sig)), "{who}: verify");
        let mut other = msg.clone();
        other.push(1);
        assert!(!Core::verify(&h(pubkey), &other, &h(&s.sig)), "{who}: verify other msg");
    }
    assert_eq!(x(&me.certify_device(&h(&f.pubs.device)).unwrap()), f.certificate, "{who}: certificate");
    assert!(Core::verify(&h(&f.pubs.account), &h(&f.pubs.device), &h(&f.certificate)));

    // Envelope → content key → body
    let k1 = me.open_inner(&h(&f.envelope)).unwrap_or_else(|e| panic!("{who}: open envelope: {e}"));
    for p in &f.ciphertexts {
        assert_eq!(x(&me.decrypt(&k1, &h(&p.ct)).unwrap()), p.pt, "{who}: decrypt");
    }
    // Wrapped key
    let k2 = me.unwrap_key(&k1, &h(&f.wrapped)).unwrap_or_else(|e| panic!("{who}: unwrap: {e}"));
    for p in &f.wrapped_ciphertexts {
        assert_eq!(x(&me.decrypt(&k2, &h(&p.ct)).unwrap()), p.pt, "{who}: decrypt wrapped");
        assert_eq!(me.decrypt(&k1, &h(&p.ct)).unwrap_err(), Error::DecryptFailed);
    }
    // Controls: someone else's envelope, a tampered envelope
    assert_eq!(me.open_inner(&h(&f.foreign_envelope)).unwrap_err(), Error::NotForMe, "{who}: foreign");
    let mut bad = h(&f.envelope);
    bad[70] ^= 1;
    assert_eq!(me.open_inner(&bad).unwrap_err(), Error::NotForMe, "{who}: tampered");

    // What this core reseals, this core also opens (round trip)
    let mut back = seeded(8);
    back.load(Slot::Enc, &h(&f.keys.enc)).unwrap();
    let env2 = me.seal_inner(&k2, &h(&f.pubs.enc)).unwrap();
    let k2b = back.open_inner(&env2).unwrap();
    assert_eq!(x(&back.decrypt(&k2b, &h(&f.wrapped_ciphertexts[2].ct)).unwrap()), f.wrapped_ciphertexts[2].pt);

    // Recovery: guardian shares → resealed to the new device's temporary key (generator side) → restore
    let r = &f.recovery;
    let backup = h(&r.backup);
    let server = h(&r.server_share);
    let mut own_resealed = Vec::new();
    for (i, g) in f.keys.guardians.iter().enumerate() {
        let mut gc = seeded(200 + i as u64);
        assert_eq!(x(&gc.load(Slot::Enc, &h(g)).unwrap()), f.pubs.guardians[i]);
        own_resealed.push(gc.reseal_share(&h(&r.guardian_shares[i]), &h(&f.pubs.recovery)).unwrap());
    }
    let theirs: Vec<Vec<u8>> = r.resealed.iter().map(|s| h(s)).collect();
    let subsets: [&[usize]; 4] = [&[0, 1], &[1, 2], &[0, 2], &[0, 1, 2]];
    for set in subsets {
        for source in [&theirs, &own_resealed] {
            let mut fresh = seeded(300);
            fresh.load(Slot::Recovery, &h(&f.keys.recovery)).unwrap();
            let shares: Vec<&[u8]> = set.iter().map(|&i| source[i].as_slice()).collect();
            let (a, e) = fresh
                .complete_recovery(&backup, &shares, &server, &h(&f.pubs.account))
                .unwrap_or_else(|err| panic!("{who}: recovery {set:?}: {err}"));
            assert_eq!((x(&a), x(&e)), (f.pubs.account.clone(), f.pubs.enc.clone()));
            assert_eq!(x(fresh.slot_secret(Slot::Account).unwrap().as_ref()), f.keys.account);
            assert_eq!(x(fresh.slot_secret(Slot::Enc).unwrap().as_ref()), f.keys.enc);
            assert!(!fresh.has(Slot::Recovery));
        }
    }
    let mut fresh = seeded(301);
    fresh.load(Slot::Recovery, &h(&f.keys.recovery)).unwrap();
    assert_eq!(
        fresh.complete_recovery(&backup, &[theirs[0].as_slice()], &server, &h(&f.pubs.account)).unwrap_err(),
        Error::RecoveryFailed,
        "{who}: one share must not recover"
    );

    for v in &f.shamir {
        let shares = shamir::split(&h(&v.secret), v.n, v.k, &h(&v.coefficients)).unwrap();
        assert_eq!(shares.iter().map(|s| x(s)).collect::<Vec<_>>(), v.shares, "{who}: shamir split");
        let first_k: Vec<Vec<u8>> = v.shares.iter().rev().take(v.k).map(|s| h(s)).collect();
        assert_eq!(x(&shamir::combine(&first_k).unwrap()), v.secret, "{who}: shamir combine");
    }
}

fn read(name: &str) -> Fixture {
    let p = dir().join(name);
    let s = std::fs::read_to_string(&p).unwrap_or_else(|_| panic!("vector file not found: {}", p.display()));
    serde_json::from_str(&s).unwrap()
}

#[test]
fn rust_vectors_are_reproducible_and_self_consistent() {
    let f = generate();
    check(&f);
    let path = dir().join("rust.json");
    if std::env::var("GORI_WRITE_VECTORS").as_deref() == Ok("1") {
        std::fs::write(&path, serde_json::to_string_pretty(&f).unwrap() + "\n").unwrap();
    }
    assert_eq!(read("rust.json"), f, "rust.json differs from the generator; regenerate it with GORI_WRITE_VECTORS=1");
}

#[test]
fn dev_core_vectors_open_in_rust() {
    let f = read("dev.json");
    assert!(f.generator.contains("JavaScript reference implementation"), "{}", f.generator);
    check(&f);
}

/// The header (include/gori_core.h) declares exactly the functions exported by src/ffi.rs
#[test]
fn header_matches_exports() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let ffi = std::fs::read_to_string(root.join("src/ffi.rs")).unwrap();
    let header = std::fs::read_to_string(root.join("include/gori_core.h")).unwrap();
    let names = |src: &str, marker: &str| {
        let mut v: Vec<String> = src
            .split(marker)
            .skip(1)
            .filter_map(|rest| {
                let name: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
                name.starts_with("gori_").then_some(name)
            })
            .collect();
        v.sort();
        v.dedup();
        v
    };
    let exported = names(&ffi, "extern \"C\" fn ");
    let mut declared: Vec<String> = header
        .lines()
        .filter(|l| !l.trim_start().starts_with('*') && !l.trim_start().starts_with("/*"))
        .flat_map(|l| l.split(|c: char| !(c.is_alphanumeric() || c == '_')).map(str::to_string).collect::<Vec<_>>())
        .filter(|w| w.starts_with("gori_") && w.len() > 5)
        .collect();
    // Keep declared function names only (followed by '('; this excludes types and macros)
    declared.retain(|w| header.contains(&format!("{w}(")));
    declared.sort();
    declared.dedup();
    assert_eq!(exported, declared);
}
